  insert into public.marketing_permission_redactions (record_id, reason, basis, confirmed_permitted, redacted_by, redacted_at) values ('00000000-0000-4000-8000-0000000a6001','retention period ended for this record','retention_period_ended',true,'00000000-0000-4000-8000-0000000a0001', now() - interval '7 years'),('00000000-0000-4000-8000-0000000a6002','retention period ended for this record','retention_period_ended',true,'00000000-0000-4000-8000-0000000a0001', now() - interval '7 years');
set session_replication_role = origin;

do $$
declare FOUNDER uuid := '00000000-0000-4000-8000-0000000a0001'; STAFF uuid := '00000000-0000-4000-8000-0000000a0002'; GA uuid := '00000000-0000-4000-8000-0000000a4000'; GB uuid := '00000000-0000-4000-8000-0000000a4001'; GC uuid := '00000000-0000-4000-8000-0000000a4002'; GD uuid := '00000000-0000-4000-8000-0000000a4003'; GD2 uuid := '00000000-0000-4000-8000-0000000a4004';
  c record; n integer; before_f integer; before_j integer;
begin
  -- 1. the old four-argument function is gone; the aligned five-argument one exists; client roles cannot run any of the new functions
  assert not exists (select 1 from pg_proc where proname = 'portfolio_subject_permission_redact' and pronargs = 4), 'old signature must be dropped';
  assert (select count(*) from pg_proc p where p.proname in ('portfolio_subject_permission_redact','portfolio_subject_permission_erasure_check','portfolio_log_purge','portfolio_log_purge_preview') and (has_function_privilege('anon', p.oid,'execute') or has_function_privilege('authenticated', p.oid,'execute'))) = 0, 'client exec'; raise notice 'PASS 1 the 0182 function is replaced by the aligned one; all new functions are server-only';
  -- 2. validation
  begin perform public.portfolio_subject_permission_redact(GB, STAFF, 'retention period ended for this record', 'data_subject_request', true); raise exception 'FAIL staff'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 2a management only';
  begin perform public.portfolio_subject_permission_redact(GB, FOUNDER, 'retention period ended for this record', 'data_subject_request', false); raise exception 'FAIL no confirmation'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 2b confirmation required';
  begin perform public.portfolio_subject_permission_redact(GB, FOUNDER, 'retention period ended for this record', 'because', true); raise exception 'FAIL bad basis'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 2c a recorded basis is required';
  begin perform public.portfolio_subject_permission_redact(GB, FOUNDER, 'short', 'data_subject_request', true); raise exception 'FAIL short reason'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 2d a reason of 10 to 200 characters is required';
  -- 3. retention basis needs a recorded policy; nothing is seeded
  select * into c from public.portfolio_subject_permission_erasure_check(GB, 'retention_period_ended'); assert c.blockers::text like '%no retention policy%', 'no policy blocks the retention basis';
  begin perform public.portfolio_subject_permission_redact(GB, FOUNDER, 'six year retention period ended for this record', 'retention_period_ended', true); raise exception 'FAIL retention basis without policy'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 3 the retention basis is refused until management records a policy';
  insert into public.portfolio_retention_policy (retention_years, policy_note, adopted_by) values (6,'six years after the permission and last use ended; longer where a duty, dispute or hold requires',FOUNDER);
  -- 4. period: the recent withdrawal (A) is refused on the retention basis; the old one (B, ended 7 years ago, last use 7.5 years ago) is allowed; a replaced-then-withdrawn permission counts from its end
  select * into c from public.portfolio_subject_permission_erasure_check(GA, 'retention_period_ended'); assert c.blockers::text like '%retention period has not ended%', 'A: recent end blocked';
  select * into c from public.portfolio_subject_permission_erasure_check(GB, 'retention_period_ended'); assert coalesce(array_length(c.blockers,1),0) = 0, 'B should be erasable: ' || c.blockers::text;
  raise notice 'PASS 4a the period runs from the later of the permission end and the last use';
  -- 5. a valid data-subject request skips the period but never the other safeguards: A (withdrawn yesterday, no hold, not in use) is erasable on that basis
  select * into c from public.portfolio_subject_permission_erasure_check(GA, 'data_subject_request'); assert coalesce(array_length(c.blockers,1),0) = 0, 'A erasable on a data-subject request: ' || c.blockers::text;
  -- 6. job-level hold (new) blocks every basis: C's job has an active hold
  select * into c from public.portfolio_subject_permission_erasure_check(GC, 'data_subject_request'); assert c.blockers::text like '%hold is in place on this photograph%', 'file hold on C: ' || c.blockers::text;
  begin perform public.portfolio_subject_permission_redact(GC, FOUNDER, 'six year retention period ended for this record', 'retention_period_ended', true); raise exception 'FAIL erased under hold'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 6a holds block every basis';
  -- 6b. job-level hold alone (no file hold): put a job hold on A's job after releasing nothing: use job A
  insert into public.marketing_permission_job_holds (job_type, job_id, action, reason, recorded_by) values ('crew_support_request','00000000-0000-4000-8000-0000000a1011','placed','job-level hold: keep all evidence',FOUNDER);
  select * into c from public.portfolio_subject_permission_erasure_check(GA, 'data_subject_request'); assert c.blockers::text like '%photograph''s job%', 'job hold on A: ' || c.blockers::text; raise notice 'PASS 6b a job-level hold now also blocks the 0182 erasure';
  insert into public.marketing_permission_job_holds (job_type, job_id, action, reason, recorded_by) values ('crew_support_request','00000000-0000-4000-8000-0000000a1011','released','job-level hold released, no further action',FOUNDER);
  -- 7. in force is refused
  select * into c from public.portfolio_subject_permission_erasure_check(GD2, 'data_subject_request'); assert coalesce(array_length(c.blockers,1),0) = 0, 'D2 was withdrawn so it can be erased'; 
  select * into c from public.portfolio_subject_permission_erasure_check(GD, 'retention_period_ended'); assert coalesce(array_length(c.blockers,1),0) = 0, 'D (replaced 7 years ago) counts from the replacement: ' || c.blockers::text; raise notice 'PASS 7 a replaced permission counts as ended from its replacement';
  -- 7b. a CURRENT covered use blocks erasure on every basis (file B is used again for the website)
  set local session_replication_role = replica; insert into public.portfolio_use_events (project_file_id, destination, action, actor_id, occurred_at) values ('00000000-0000-4000-8000-0000000a1024','website','published',FOUNDER, now() - interval '7 years 3 months'); set local session_replication_role = origin;
  select * into c from public.portfolio_subject_permission_erasure_check(GB, 'data_subject_request'); assert c.blockers::text like '%still in use%', 'in use blocks: ' || c.blockers::text;
  begin perform public.portfolio_subject_permission_redact(GB, FOUNDER, 'data subject asked for erasure of details', 'data_subject_request', true); raise exception 'FAIL erased while in use'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end;
  set local session_replication_role = replica; insert into public.portfolio_use_events (project_file_id, destination, action, actor_id, occurred_at) values ('00000000-0000-4000-8000-0000000a1024','website','ended',FOUNDER, now() - interval '7 years 2 months'); set local session_replication_role = origin;
  raise notice 'PASS 7b a current covered use blocks erasure on every basis';
  -- 7c. nothing deletes automatically: only the controlled purge function deletes from the four log tables, and no scheduled job refers to it
  assert not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public','private') and p.proname <> 'portfolio_log_purge' and p.prosrc ~* 'delete\s+from\s+public\.(portfolio_subject_redactions|portfolio_file_holds|marketing_permission_redactions|marketing_permission_job_holds)'), 'only the purge function deletes log rows';
  if to_regclass('cron.job') is not null then execute 'select count(*) from cron.job where command ilike ''%portfolio_log_purge%''' into n; assert n = 0, 'no scheduled purge'; end if;
  raise notice 'PASS 7c no automatic deletion exists';
  -- 7d. the eligibility function and the 0182 append-only guards are untouched
  assert pg_get_functiondef('public.portfolio_use_eligibility(uuid,text,date)'::regprocedure) like '%people_not_declared%' and pg_get_functiondef('public.portfolio_use_eligibility(uuid,text,date)'::regprocedure) like '%destination_not_approved%', 'eligibility intact';
  begin update public.portfolio_subject_permissions set allowed_destinations = array['portfolio'] where id = GB; raise exception 'FAIL permissions edited'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end;
  begin delete from public.portfolio_file_subjects; raise exception 'FAIL subjects deleted'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end;
  raise notice 'PASS 7d the eligibility function and the append-only guards are intact';
  -- 8. erase B (retention) and A (data-subject request); structure kept; basis logged
  perform public.portfolio_subject_permission_redact(GB, FOUNDER, 'six year retention period ended for this record', 'retention_period_ended', true);
  perform public.portfolio_subject_permission_redact(GA, FOUNDER, 'data subject asked for erasure of details', 'data_subject_request', true);
  assert (select grantor_name from public.portfolio_subject_permissions where id = GB) = '[erased]' and (select decision from public.portfolio_subject_permissions where id = GB) = 'granted', 'B erased, structure kept';
  assert (select count(*) from public.portfolio_subject_redactions where permission_id in (GB, GA) and basis is not null) >= 2, 'bases logged'; raise notice 'PASS 8 erasure on both bases works and keeps the decision structure';
  -- 9. PURGE preview and function
  select count(*) into n from public.portfolio_log_purge_preview() where cutoff_date is not null; assert n = 4, 'preview covers four tables with a cutoff';
  begin perform public.portfolio_log_purge('portfolio_file_holds', STAFF, 'retention_period_expired', true); raise exception 'FAIL staff purge'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 9a purge is management only';
  begin perform public.portfolio_log_purge('portfolio_file_holds', FOUNDER, 'retention_period_expired', false); raise exception 'FAIL purge without confirmation'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 9b purge needs confirmation';
  begin perform public.portfolio_log_purge('some_other_table', FOUNDER, 'retention_period_expired', true); raise exception 'FAIL other table'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 9c only the four log tables';
  begin delete from public.portfolio_file_holds; raise exception 'FAIL direct delete'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end;
  begin update public.portfolio_file_holds set reason = 'edited reason of the hold'; raise exception 'FAIL update'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 9d log rows cannot be edited or deleted outside the purge';
  -- 9d2. ATOMIC: if the permanent audit row cannot be written, the deletion is undone (one function, one transaction)
  execute 'create function public.zz_fail_audit() returns trigger language plpgsql as $f$ begin raise exception ''forced audit failure''; end $f$';
  execute 'create trigger zz_fail_audit before insert on public.portfolio_log_purges for each row execute function public.zz_fail_audit()';
  select count(*) into n from public.portfolio_file_holds;
  begin perform public.portfolio_log_purge('portfolio_file_holds', FOUNDER, 'retention_period_expired', true); raise exception 'FAIL purge succeeded without its audit row'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end;
  assert (select count(*) from public.portfolio_file_holds) = n, 'the deletion must be rolled back with the failed audit';
  assert (select count(*) from public.portfolio_log_purges) = 0, 'no audit row exists';
  execute 'drop trigger zz_fail_audit on public.portfolio_log_purges'; execute 'drop function public.zz_fail_audit()';
  raise notice 'PASS 9d2 a purge is atomic with its permanent audit row (a failed audit undoes the deletion)';
  -- file-hold log: B chain (placed 8y, released 7y6m) eligible = 2 rows; C chain active hold protected = 0; A chain (placed 1y, released 11m) too recent
  select eligible_rows into n from public.portfolio_log_purge_preview() where log_table = 'portfolio_file_holds'; assert n = 2, 'file hold eligible rows: ' || n;
  n := public.portfolio_log_purge('portfolio_file_holds', FOUNDER, 'retention_period_expired', true); assert n = 2, 'purged 2';
  assert (select count(*) from public.portfolio_file_holds where project_file_id = '00000000-0000-4000-8000-0000000a1034') = 1 and (select count(*) from public.portfolio_file_holds where project_file_id = '00000000-0000-4000-8000-0000000a1014') = 2, 'active-hold chain and recent chain kept';
  assert (select action from public.portfolio_file_holds where project_file_id = '00000000-0000-4000-8000-0000000a1034') = 'placed', 'active hold still active';
  -- job-hold log: B chain eligible (2), C placed protected, A recent (placed+released within the last minutes) kept
  n := public.portfolio_log_purge('marketing_permission_job_holds', FOUNDER, 'annual_retention_review', true); assert n = 2, 'job holds purged: ' || n;
  assert (select count(*) from public.marketing_permission_job_holds where job_id = '00000000-0000-4000-8000-0000000a1031') = 1, 'C job hold kept';
  -- subject redaction log: GB old and free -> purged; GC old but under an active hold -> kept; GA recent (1 year) -> kept; plus the two new rows from step 8 are recent -> kept
  n := public.portfolio_log_purge('portfolio_subject_redactions', FOUNDER, 'retention_period_expired', true); assert n = 1, 'subject redaction log purged: ' || n;
  assert exists (select 1 from public.portfolio_subject_redactions where permission_id = GC), 'held row kept';
  -- marketing redaction log: MB old and free -> purged; MC old under job hold -> kept
  n := public.portfolio_log_purge('marketing_permission_redactions', FOUNDER, 'retention_period_expired', true); assert n = 1, 'marketing redaction log purged: ' || n;
  assert (select count(*) from public.marketing_permission_redactions) = 1, 'held row kept'; raise notice 'PASS 9e the purge deletes only expired rows with no active hold, in each of the four logs';
  begin perform public.portfolio_log_purge('portfolio_file_holds', FOUNDER, 'a free text reason with Jane Doe', true); raise exception 'FAIL free-text reason accepted'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 9f the purge reason is a fixed code, never free text';
  -- 9g. REVISION 3 corrections. (i) a hold at EITHER level protects hold-log rows; (ii) the permission ENDED at the earliest end event; (iii) a removed person's grant is not in force; (iv) the locks are present
  set local session_replication_role = replica;
  insert into public.portfolio_file_holds (project_file_id, action, reason, recorded_by, recorded_at) values ('00000000-0000-4000-8000-0000000a1044','placed','old dispute about the photograph','00000000-0000-4000-8000-0000000a0001', now() - interval '8 years'),('00000000-0000-4000-8000-0000000a1044','released','old dispute closed, no action','00000000-0000-4000-8000-0000000a0001', now() - interval '7 years 6 months');
  insert into public.marketing_permission_job_holds (job_type, job_id, action, reason, recorded_by, recorded_at) values ('crew_support_request','00000000-0000-4000-8000-0000000a1041','placed','old audit of the job','00000000-0000-4000-8000-0000000a0001', now() - interval '8 years'),('crew_support_request','00000000-0000-4000-8000-0000000a1041','released','old audit closed, no action','00000000-0000-4000-8000-0000000a0001', now() - interval '7 years 6 months');
  set local session_replication_role = origin;
  select eligible_rows into n from public.portfolio_log_purge_preview() where log_table = 'portfolio_file_holds'; before_f := n;
  select eligible_rows into n from public.portfolio_log_purge_preview() where log_table = 'marketing_permission_job_holds'; before_j := n;
  insert into public.marketing_permission_job_holds (job_type, job_id, action, reason, recorded_by) values ('crew_support_request','00000000-0000-4000-8000-0000000a1041','placed','a current job-level hold',FOUNDER);
  select eligible_rows into n from public.portfolio_log_purge_preview() where log_table = 'portfolio_file_holds'; assert n = before_f - 2, 'a job-level hold protects the file-level hold log rows of its photographs: ' || n || ' vs ' || before_f;
  insert into public.marketing_permission_job_holds (job_type, job_id, action, reason, recorded_by) values ('crew_support_request','00000000-0000-4000-8000-0000000a1041','released','the job-level hold released',FOUNDER);
  select eligible_rows into n from public.portfolio_log_purge_preview() where log_table = 'portfolio_file_holds'; assert n = before_f, 'released: file-level rows eligible again';
  insert into public.portfolio_file_holds (project_file_id, action, reason, recorded_by) values ('00000000-0000-4000-8000-0000000a1044','placed','a current photograph-level hold',FOUNDER);
  select eligible_rows into n from public.portfolio_log_purge_preview() where log_table = 'marketing_permission_job_holds'; assert n = before_j - 2, 'a photograph-level hold protects the job-level hold log rows of its job: ' || n || ' vs ' || before_j;
  insert into public.portfolio_file_holds (project_file_id, action, reason, recorded_by) values ('00000000-0000-4000-8000-0000000a1044','released','the photograph-level hold released',FOUNDER);
  raise notice 'PASS 9g a hold at either level protects the hold-log rows of the other level';
  -- 9h. earliest end: expired 8 years ago but withdrawn only a year ago: the clock started at the expiry
  set local session_replication_role = replica;
  insert into public.portfolio_file_subjects (id, project_file_id, action, subject_kind, label, recorded_by, recorded_at) values ('00000000-0000-4000-8000-0000000a9001','00000000-0000-4000-8000-0000000a1044','added','adult','guest near the door','00000000-0000-4000-8000-0000000a0001', now() - interval '10 years'),('00000000-0000-4000-8000-0000000a9002','00000000-0000-4000-8000-0000000a1044','added','adult','guest at the bar','00000000-0000-4000-8000-0000000a0001', now() - interval '10 years');
  insert into public.portfolio_subject_permissions (id, subject_id, decision, grantor_kind, grantor_name, evidence_kind, evidence_reference, given_on, allowed_destinations, expires_on, recorded_by, recorded_at) values ('00000000-0000-4000-8000-0000000a9011','00000000-0000-4000-8000-0000000a9001','granted','subject_self','Guest Door','written_message','guest email kept in the job folder',(now() - interval '11 years')::date,array['website'],(now() - interval '8 years')::date,'00000000-0000-4000-8000-0000000a0001', now() - interval '11 years');
  insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, evidence_reference, note, recorded_by, recorded_at) values ('00000000-0000-4000-8000-0000000a9001','verified','00000000-0000-4000-8000-0000000a9011','guest email kept in the job folder','verified after checking the message','00000000-0000-4000-8000-0000000a0001', now() - interval '11 years'),('00000000-0000-4000-8000-0000000a9001','withdrawn','00000000-0000-4000-8000-0000000a9011','guest email kept in the job folder','withdrawn after checking the message','00000000-0000-4000-8000-0000000a0001', now() - interval '1 year');
  set local session_replication_role = origin;
  select * into c from public.portfolio_subject_permission_erasure_check('00000000-0000-4000-8000-0000000a9011', 'retention_period_ended');
  assert c.ended_on = (current_date - interval '8 years')::date and coalesce(array_length(c.blockers, 1), 0) = 0, 'the permission ended at its expiry, not at the later withdrawal: ' || coalesce(c.ended_on::text, 'null') || ' ' || coalesce(c.blockers::text, '');
  raise notice 'PASS 9h the retention clock starts at the earliest end event';
  -- 9i. a person removed from the photograph: their verified, never-withdrawn grant is no longer in force and the removal date is the end
  set local session_replication_role = replica;
  insert into public.portfolio_subject_permissions (id, subject_id, decision, grantor_kind, grantor_name, evidence_kind, evidence_reference, given_on, allowed_destinations, recorded_by, recorded_at) values ('00000000-0000-4000-8000-0000000a9021','00000000-0000-4000-8000-0000000a9002','granted','subject_self','Guest Bar','written_message','guest email kept in the job folder',(now() - interval '11 years')::date,array['website'],'00000000-0000-4000-8000-0000000a0001', now() - interval '11 years');
  insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, evidence_reference, note, recorded_by, recorded_at) values ('00000000-0000-4000-8000-0000000a9002','verified','00000000-0000-4000-8000-0000000a9021','guest email kept in the job folder','verified after checking the message','00000000-0000-4000-8000-0000000a0001', now() - interval '11 years');
  set local session_replication_role = origin;
  select * into c from public.portfolio_subject_permission_erasure_check('00000000-0000-4000-8000-0000000a9021', 'data_subject_request'); assert c.blockers::text like '%still in force%', 'before removal the grant is in force';
  set local session_replication_role = replica;
  insert into public.portfolio_file_subjects (project_file_id, action, subject_kind, label, supersedes_id, recorded_by, recorded_at) values ('00000000-0000-4000-8000-0000000a1044','removed','adult','guest at the bar','00000000-0000-4000-8000-0000000a9002','00000000-0000-4000-8000-0000000a0001', now() - interval '7 years');
  set local session_replication_role = origin;
  select * into c from public.portfolio_subject_permission_erasure_check('00000000-0000-4000-8000-0000000a9021', 'retention_period_ended');
  assert c.ended_on = (current_date - interval '7 years')::date and coalesce(array_length(c.blockers, 1), 0) = 0, 'removal ends the permission: ' || coalesce(c.ended_on::text, 'null') || ' ' || coalesce(c.blockers::text, '');
  raise notice 'PASS 9i a removed person''s grant is not in force and the removal date starts the clock';
  -- 9j. the concurrency locks are present in the function bodies
  assert (select prosrc from pg_proc where proname = 'portfolio_subject_permission_redact' and pronargs = 5) ~* 'for update', 'redact locks the grant row';
  assert (select prosrc from pg_proc where proname = 'portfolio_log_purge') ~* 'lock table public.portfolio_file_holds, public.marketing_permission_job_holds in share row exclusive mode', 'purge locks the hold tables';
  raise notice 'PASS 9j the erasure and the purge take the concurrency locks';
  -- 10. permanent audit of purges, append-only, never purgeable
  assert (select count(*) from public.portfolio_log_purges) = 4, 'four purge audit rows';
  assert (select array_agg(column_name::text order by column_name) from information_schema.columns where table_schema = 'public' and table_name = 'portfolio_log_purges') = array['business_id','confirmed','cutoff_date','id','purged_at','purged_by','purged_table','reason_code','retention_years','rows_purged'], 'the permanent purge audit holds only necessary metadata';
  begin delete from public.portfolio_log_purges; raise exception 'FAIL purge audit deleted'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end;
  begin update public.portfolio_log_purges set rows_purged = 0; raise exception 'FAIL purge audit edited'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 10 every purge leaves a permanent, append-only audit row';
  -- 11. without a policy nothing can be purged (policy rows are append-only; simulate with a purge on a fresh table state is covered by 3); privileges
  assert (select count(*) from information_schema.role_table_grants where table_name = 'portfolio_log_purges' and grantee in ('anon','authenticated','PUBLIC')) = 0, 'client grants';
  assert (select count(*) from information_schema.role_table_grants where table_name = 'portfolio_log_purges' and grantee='service_role' and privilege_type in ('DELETE','TRUNCATE','UPDATE','REFERENCES','TRIGGER','MAINTAIN')) = 0, 'dangerous grants';
  assert (select relrowsecurity from pg_class where relname = 'portfolio_log_purges'), 'rls'; raise notice 'PASS 11 purge audit table: RLS on, no client access, no update or delete for the service role';
end $$;
-- 12. L6 (revision 4): the database refuses to verify an erased permission, from any writer. Seeds bypass the guards (replica); every test then runs with the guards ON.
set session_replication_role = replica;
  insert into public.portfolio_file_subjects (id, project_file_id, action, subject_kind, label, recorded_by) values ('00000000-0000-4000-8000-0000000a3005','00000000-0000-4000-8000-0000000a1014','added','adult','guest E','00000000-0000-4000-8000-0000000a0001'),('00000000-0000-4000-8000-0000000a3006','00000000-0000-4000-8000-0000000a1014','added','adult','guest F','00000000-0000-4000-8000-0000000a0001'),('00000000-0000-4000-8000-0000000a3007','00000000-0000-4000-8000-0000000a1014','added','adult','guest G','00000000-0000-4000-8000-0000000a0001');
  insert into public.portfolio_subject_permissions (id, subject_id, decision, grantor_kind, grantor_name, evidence_kind, evidence_reference, given_on, allowed_destinations, recorded_by) values
    ('00000000-0000-4000-8000-0000000a4005','00000000-0000-4000-8000-0000000a3005','granted','subject_self','Guest E','written_message','guest email kept in the job folder',current_date,array['portfolio'],'00000000-0000-4000-8000-0000000a0001'),
    ('00000000-0000-4000-8000-0000000a4006','00000000-0000-4000-8000-0000000a3006','granted','subject_self','Guest F','written_message','guest email kept in the job folder',current_date,array['portfolio'],'00000000-0000-4000-8000-0000000a0001'),
    ('00000000-0000-4000-8000-0000000a4007','00000000-0000-4000-8000-0000000a3007','granted','subject_self','Guest G','written_message','guest email kept in the job folder',current_date,array['portfolio'],'00000000-0000-4000-8000-0000000a0001');
set session_replication_role = origin;
do $$
declare FOUNDER uuid := '00000000-0000-4000-8000-0000000a0001'; NE uuid := '00000000-0000-4000-8000-0000000a4005'; SE uuid := '00000000-0000-4000-8000-0000000a3005'; NF uuid := '00000000-0000-4000-8000-0000000a4006'; SF uuid := '00000000-0000-4000-8000-0000000a3006'; GA uuid := '00000000-0000-4000-8000-0000000a4000'; SA uuid := '00000000-0000-4000-8000-0000000a3001';
  nr uuid; refused boolean;
begin
  assert exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid where c.relname = 'portfolio_subject_permissions' and t.tgname = 'portfolio_subject_permission_erased_guard' and t.tgenabled = 'O' and (t.tgtype & 2) = 2 and (t.tgtype & 4) = 4), 'the erased guard is a BEFORE INSERT trigger and enabled';
  assert pg_get_functiondef('private.portfolio_subject_permission_erased_guard()'::regprocedure) ilike '%for share%', 'the guard serialises against a concurrent erasure';
  assert not has_function_privilege('anon', 'private.portfolio_subject_permission_erased_guard()'::regprocedure, 'execute') and not has_function_privilege('authenticated', 'private.portfolio_subject_permission_erased_guard()'::regprocedure, 'execute'), 'no client execute';
  -- a recorded, never-verified, never-withdrawn grant is erased (the case the 0182 guard alone would let through)
  perform public.portfolio_subject_permission_redact(NE, FOUNDER, 'data subject asked for erasure of details', 'data_subject_request', true);
  assert (select grantor_name from public.portfolio_subject_permissions where id = NE) = '[erased]', 'NE erased';
  assert not exists (select 1 from public.portfolio_subject_permissions w where w.supersedes_id = NE and w.decision in ('withdrawn', 'granted')), 'NE is neither withdrawn nor replaced, so only the new guard can stop its verification';
  -- 12a. a direct verification of the erased grant is refused
  refused := false;
  begin insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, evidence_reference, note, recorded_by) values (SE, 'verified', NE, 'guest email kept in the job folder', 'verified after checking the message', FOUNDER);
  exception when others then refused := sqlerrm like '%erased%'; end;
  assert refused, 'a direct verification of an erased grant must be refused';
  raise notice 'PASS 12a a direct database write cannot verify an erased permission';
  -- 12b. still refused after the erasure LOG row is purged (the marker on the grant itself holds)
  perform set_config('ordift.log_purge', 'on', true); delete from public.portfolio_subject_redactions where permission_id = NE; perform set_config('ordift.log_purge', 'off', true);
  assert not exists (select 1 from public.portfolio_subject_redactions where permission_id = NE), 'log row gone';
  refused := false;
  begin insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, evidence_reference, note, recorded_by) values (SE, 'verified', NE, 'guest email kept in the job folder', 'verified after checking the message', FOUNDER);
  exception when others then refused := sqlerrm like '%erased%'; end;
  assert refused, 'still refused after the erasure log row was purged';
  raise notice 'PASS 12b the refusal survives a purge of the erasure log';
  -- 12c. the refusal does not depend on the marker text alone: with the marker absent but a log row present it is also refused
  perform set_config('ordift.redaction', 'on', true); update public.portfolio_subject_permissions set grantor_name = 'Guest F' where id = NF; perform set_config('ordift.redaction', 'off', true);
  insert into public.portfolio_subject_redactions (permission_id, reason, basis, confirmed_permitted, redacted_by) values (NF, 'log row present for this record', 'other_documented', true, FOUNDER);
  refused := false;
  begin insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, evidence_reference, note, recorded_by) values (SF, 'verified', NF, 'guest email kept in the job folder', 'verified after checking the message', FOUNDER);
  exception when others then refused := sqlerrm like '%erased%'; end;
  assert refused, 'a log row alone also blocks verification';
  raise notice 'PASS 12c either marker alone blocks verification';
  -- 12d. an already withdrawn or replaced erased grant stays refused (existing protections untouched)
  refused := false;
  begin insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, evidence_reference, note, recorded_by) values (SA, 'verified', GA, 'guest email kept in the job folder', 'verified after checking the message', FOUNDER);
  exception when others then refused := true; end;
  assert refused, 'the erased and withdrawn grant stays refused';
  -- 12e. NEW evidence is allowed: a replacement permission for the erased grant is recorded and then ordinarily verified (no restoration of the erased one)
  insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, grantor_kind, grantor_name, evidence_kind, evidence_reference, given_on, allowed_destinations, recorded_by) values (SE, 'granted', NE, 'subject_self', 'Guest E', 'written_message', 'new guest email kept in the job folder', current_date, array['portfolio'], FOUNDER) returning id into nr;
  insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, evidence_reference, note, recorded_by) values (SE, 'verified', nr, 'new guest email kept in the job folder', 'verified after checking the new message', FOUNDER);
  assert (select count(*) from public.portfolio_subject_permissions where supersedes_id = nr and decision = 'verified') = 1, 'ordinary verification of a new, non-erased permission works';
  assert (select grantor_name from public.portfolio_subject_permissions where id = NE) = '[erased]', 'the erased grant stays erased';
  raise notice 'PASS 12d/12e existing refusals intact; a new permission is recorded and verified normally';
  -- 12f. withdrawal of an erased grant is not blocked (protective)
  insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, note, recorded_by) values (SE, 'withdrawn', NE, 'withdrawn after the erasure', FOUNDER);
  assert exists (select 1 from public.portfolio_subject_permissions where supersedes_id = NE and decision = 'withdrawn'), 'withdrawal still works';
  raise notice 'PASS 12f a withdrawal is never blocked';
  -- 12g. ordinary verification of a recorded, non-erased grant still works through the live guards, and is then in force for its destination
  insert into public.portfolio_subject_permissions (subject_id, decision, supersedes_id, evidence_reference, note, recorded_by) values ('00000000-0000-4000-8000-0000000a3007', 'verified', '00000000-0000-4000-8000-0000000a4007', 'guest email kept in the job folder', 'verified after checking the message', FOUNDER);
  assert exists (select 1 from public.portfolio_subject_permissions where supersedes_id = '00000000-0000-4000-8000-0000000a4007' and decision = 'verified'), 'ordinary verification works';
  raise notice 'PASS 12g ordinary verification of a non-erased permission still works';
end $$;

rollback;
